html_template:
{% set bpak_serial_number = doc.get('bpak_serial_number') or doc.get('serial_number') or doc.get('name') or 'серійний_номер_БпАК' %}

<div style="
    width:885px;
    height:590px;
    margin:0 auto;
    padding:0;
    box-sizing:border-box;
    position:relative;
    overflow:hidden;
    background:#fff;
    color:#000;
    font-family:Arial,sans-serif;
    border:none;
    outline:none;
">
    <div style="
        position:absolute;
        left:0;
        top:24%;
        transform:translateY(-50%);
        width:820px;
        text-align:center;
        font-weight:700;
        line-height:1.08;
        border:none;
        outline:none;
    ">
        <div style="font-size:76px;">БпАК:</div>
        <div style="font-size:58px; white-space:nowrap;">{{ bpak_serial_number }}</div>
    </div>
</div>

{%- set items = doc.get("items") or [] -%}
{%- set first = items[0] if items else {} -%}
{%- set title = (first.item_name or first.item_code or "") | replace(".", " ") -%}
{%- set ns = namespace(km="") -%}
{%- for w in title.split() -%}{%- if not ns.km and w.isdigit() -%}{%- set ns.km = w -%}{%- endif -%}{%- endfor -%}
{%- set n = items | length -%}
{%- if n % 10 == 1 and n % 100 != 11 -%}{%- set word = "Котушка" -%}
{%- elif n % 10 in [2, 3, 4] and n % 100 not in [12, 13, 14] -%}{%- set word = "Котушки" -%}
{%- else -%}{%- set word = "Котушок" -%}{%- endif -%}
<div style="position:relative;width:100%;height:100%;font-family:Arial,sans-serif;color:#000;background:#fff;">
  <div style="position:absolute;left:0;top:40px;width:100%;text-align:center;font-size:150px;font-weight:bold;line-height:1;">Укропчик<span style="font-size:70px;vertical-align:top;position:relative;top:4px;">™</span></div>
  <svg style="position:absolute;left:40px;top:370px;width:540px;height:440px;" viewBox="0 0 700 570" xmlns="http://www.w3.org/2000/svg"><path d="M350 0 C360 0 365 9 371 18 L448 142 C477 188 470 230 439 264 L386 323 C376 334 365 343 356 349 C358 328 365 293 373 260 C384 215 373 154 350 112 C327 154 316 215 327 260 C335 293 342 328 344 349 C335 343 324 334 314 323 L261 264 C230 230 223 188 252 142 L329 18 C335 9 340 0 350 0 Z" fill="#000"/><path d="M205 244 C213 236 224 237 231 249 C267 310 308 341 336 354 C279 363 232 389 196 443 L137 533 C128 547 115 553 99 550 L0 534 Z" fill="#000"/><path d="M495 244 C487 236 476 237 469 249 C433 310 392 341 364 354 C421 363 468 389 504 443 L563 533 C572 547 585 553 601 550 L700 534 Z" fill="#000"/><path d="M340 366 C308 393 280 448 260 517 C256 531 261 540 276 543 C307 549 331 561 350 570 C369 561 393 549 424 543 C439 540 444 531 440 517 C420 448 392 393 360 366 C364 408 365 455 350 512 C335 455 336 408 340 366 Z" fill="#000"/><path d="M350 112 C327 154 316 215 327 260 C335 293 342 328 344 349 C346 350 348 351 350 352 C352 351 354 350 356 349 C358 328 365 293 373 260 C384 215 373 154 350 112 Z" fill="#fff"/></svg>
  <div style="position:absolute;left:560px;top:350px;width:560px;text-align:left;font-size:76px;white-space:nowrap;font-weight:bold;line-height:1;">Fiber Optic</div>
  <div style="position:absolute;left:600px;top:460px;width:480px;text-align:left;font-size:330px;font-weight:bold;line-height:1;">{{ ns.km }}</div>
  <div style="position:absolute;left:0;top:890px;width:100%;text-align:center;font-size:110px;line-height:1;">{{ n }} {{ word }}</div>
</div>

{% set model_name = doc.bpak_template_name or '' %}
{% set packages = frappe.get_all('Package', filters={'bpak': doc.name, 'docstatus': ['<', 2]}, fields=['name'], limit_page_length=0) %}
{% set ns = namespace(bpla=[]) %}
{% for pkg in packages %}
  {% set rows = frappe.get_all('Package Item', filters={'parent': pkg.name, 'parenttype': 'Package'}, fields=['item_code', 'serial_no'], limit_page_length=0) %}
  {% for r in rows %}
    {% if r.serial_no %}
      {% set ig = (frappe.db.get_value('Item', r.item_code, 'item_group') or '') | lower %}
      {% if 'бпла' in ig or 'укропчик' in ig %}
        {% for s in r.serial_no.replace('\r','').split('\n') %}
          {% set s = s | trim %}
          {% if s %}{% set ns.bpla = ns.bpla + [s] %}{% endif %}
        {% endfor %}
      {% endif %}
    {% endif %}
  {% endfor %}
{% endfor %}
{% set bpla = ns.bpla | sort %}
{% set qr_text = bpla | join('\r\n') %}
{% set qty = bpla | length %}
{% set capacity = 100 %}

<div style="width:100%;height:100%;text-align:center;padding-top:0;box-sizing:border-box;font-family:Arial,sans-serif;color:#000;overflow:hidden;">
{% if qr_text %}<img src="https://api.qrserver.com/v1/create-qr-code/?size=2200x2200&ecc=L&margin=40&format=svg&data={{ qr_text | urlencode }}" width="950" height="950" style="width:950px;height:950px;display:block;margin:0 auto;">{% endif %}
<div style="width:88%;border-top:3px solid #000;margin:28px auto 8px auto;"></div>
<div style="font-size:32px;font-weight:bold;line-height:1.08;margin:0 0 7px 0;">БпАК "{{ model_name }}"</div>
<div style="font-size:27px;font-weight:bold;line-height:1.08;margin:0;">Загальний QR БпЛА. К-ть: {{ qty }}/{{ capacity }} шт.</div>
</div>

{%- set d = doc|default({}) -%}
{%- set running_no = (d.num or d.name or '')|string -%}
{%- set generated_code = 'UFOS' ~ (d.xx or '') ~ (d.yy or '') ~ (d.nn or '') ~ running_no.zfill(6) -%}
{%- set coil_code = d.coil_code or d.код_виробу or d.serial_no or d.item_code or generated_code or 'UFOS252501002400' -%}
{%- set raw_label_date = d.label_date_formatted or d.label_date or d.posting_date or d.modified or '' -%}
{%- set label_date = raw_label_date|string -%}
{%- if label_date|length >= 10 and label_date[4:5] == '-' and label_date[7:8] == '-' -%}
  {%- set label_date = label_date[8:10] ~ '/' ~ label_date[5:7] ~ '/' ~ label_date[2:4] -%}
{%- endif -%}

{%- set product_name = d.product_name or d.назва_за_єскд or d.назва or d.item_name or 'УКРОПЧИК FO' -%}
{%- set fiber_type = d.fiber_type or d.тип_волокна or d.custom_fiber_type or 'G657/A2' -%}
{%- set raw_length = d.fiber_length or d.довжина_намотки_км or d.custom_fiber_length or d.length or '' -%}
{%- set fiber_length = raw_length ~ 'КМ +-1%' if raw_length else '25КМ +-1%' -%}
{%- set wave_video = d.довжина_хвилі_відеосигналу_нм or '' -%}
{%- set wave_control = d.довжина_хвилі_сигналу_керування_нм or '' -%}
{%- set wavelength = d.wavelength or d.custom_wavelength or ((wave_video|string) ~ ' / ' ~ (wave_control|string) if wave_video and wave_control else '1310 / 1550') -%}
{%- set average_twist = d.average_twist or d.custom_average_twist or d.товщина_оптоволокна or '&lt;0.35 / &lt;0.23' -%}
{%- set loss_db = d.loss_db or d.custom_loss_db or d.затухання_сишналу_на_двожинах_хвиль_13101550_не_більше or '&lt;8.70 / &lt;5.60' -%}

<div style="
  width:590px;
  height:472px;
  box-sizing:border-box;
  overflow:hidden;
  background:#fff;
  color:#000;
  font-family:Arial,Helvetica,sans-serif;
  line-height:1;
">
  <table style="width:100%;height:100%;border-collapse:collapse;table-layout:fixed;">
    <tr>
      <td style="width:160px;height:472px;vertical-align:top;text-align:center;padding:48px 6px 18px 8px;box-sizing:border-box;">
        <div style="width:116px;height:116px;margin:0 auto;">
          <barcode type="qr" data="{{ coil_code }}" size="7" style="width:116px;height:116px;display:block;" />
        </div>

        <div style="font-family:'Arial Narrow',Arial,sans-serif;font-size:13px;font-weight:700;line-height:1;margin-top:5px;white-space:nowrap;letter-spacing:0;">
          {{ coil_code }}
        </div>

        <div style="height:140px;"></div>

        <attachment name="Укропчик.jpeg" style="display:block;width:128px;height:112px;object-fit:contain;margin:0 auto;" />
      </td>

      <td style="width:18px;height:472px;vertical-align:top;padding:0;box-sizing:border-box;">
        <div style="width:12px;height:472px;border-left:4px solid #000;border-right:4px solid #000;margin:0 auto;box-sizing:border-box;"></div>
      </td>

      <td style="width:412px;height:472px;vertical-align:top;padding:18px 12px 18px 6px;box-sizing:border-box;">
        <table style="width:100%;height:436px;border-collapse:collapse;table-layout:fixed;border:4px solid #000;">
          <tr>
            <td style="width:104px;border:3px solid #000;text-align:center;vertical-align:middle;font-size:20px;">Назва</td>
            <td style="border:3px solid #000;text-align:center;vertical-align:middle;font-size:34px;white-space:nowrap;">{{ product_name }}</td>
          </tr>
          <tr>
            <td style="border:3px solid #000;text-align:center;vertical-align:middle;font-size:20px;">Волокно</td>
            <td style="border:3px solid #000;text-align:center;vertical-align:middle;font-size:36px;white-space:nowrap;">{{ fiber_type }}</td>
          </tr>
          <tr>
            <td style="border:3px solid #000;text-align:center;vertical-align:middle;font-size:20px;">Довжина</td>
            <td style="border:3px solid #000;text-align:center;vertical-align:middle;font-size:36px;white-space:nowrap;">{{ fiber_length }}</td>
          </tr>
          <tr>
            <td style="border:3px solid #000;text-align:center;vertical-align:middle;font-size:20px;">Хвиля</td>
            <td style="border:3px solid #000;text-align:center;vertical-align:middle;font-size:36px;white-space:nowrap;">{{ wavelength }}</td>
          </tr>
          <tr>
            <td style="border:3px solid #000;text-align:center;vertical-align:middle;font-size:18px;line-height:1.05;">Ср.Вит<br>км</td>
            <td style="border:3px solid #000;text-align:center;vertical-align:middle;font-size:34px;white-space:nowrap;">{{ average_twist|safe }}</td>
          </tr>
          <tr>
            <td style="border:3px solid #000;text-align:center;vertical-align:middle;font-size:18px;line-height:1.05;">Витрати<br>dB</td>
            <td style="border:3px solid #000;text-align:center;vertical-align:middle;font-size:34px;white-space:nowrap;">{{ loss_db|safe }}</td>
          </tr>
          <tr>
            <td style="border:3px solid #000;text-align:center;vertical-align:middle;font-size:20px;">Код</td>
            <td style="border:3px solid #000;text-align:center;vertical-align:middle;font-family:'Arial Narrow',Arial,sans-serif;font-size:25px;font-stretch:condensed;white-space:nowrap;letter-spacing:0;">{{ coil_code }}</td>
          </tr>
          <tr>
            <td style="border:3px solid #000;text-align:center;vertical-align:middle;font-size:20px;">Дата</td>
            <td style="border:3px solid #000;text-align:center;vertical-align:middle;font-size:36px;white-space:nowrap;">{{ label_date }}</td>
          </tr>
        </table>
      </td>
    </tr>
  </table>
</div>

