{% set model_name = doc.bpak_template_name or '' %}
{% set bpak_doc = frappe.get_doc('BpAK', doc.bpak) if doc.bpak else None %}
{% set bpak_serial = bpak_doc.serial_no if bpak_doc else (doc.bpak or doc.name) %}
{% set siblings = frappe.get_all('Pallet', filters={'bpak': doc.bpak, 'docstatus': ['<', 2]}, fields=['name'], order_by='creation asc') if doc.bpak else [] %}
{% set ns = namespace(idx=1, total=siblings | length or 1) %}
{% for p in siblings %}{% if p.name == doc.name %}{% set ns.idx = loop.index %}{% endif %}{% endfor %}
{% set place_text = ns.idx ~ '/' ~ ns.total %}
