<div style="width:1050px;height:1050px;margin:0 auto;padding:0;box-sizing:border-box;position:relative;overflow:hidden;background:#fff;color:#000;font-family:Arial,sans-serif;">
<div style="position:absolute;left:70px;top:55px;width:910px;text-align:center;font-size:58px;font-weight:700;line-height:1.05;">БпАК "{{ model_name }}"</div>
<div style="position:absolute;left:95px;top:195px;width:860px;height:180px;overflow:hidden;"><barcode type="code128" data="{{ bpak_serial }}" module_width="0.95" module_height="145" style="width:860px;height:180px;display:block;"/></div>
