<div style="position:absolute;left:80px;bottom:92px;font-size:58px;font-weight:700;line-height:1;white-space:nowrap;">{{ label_date }}</div>
<div style="position:absolute;right:70px;bottom:55px;width:250px;height:250px;border:9px solid #000;box-sizing:border-box;display:table;font-size:96px;font-weight:700;line-height:1;text-align:center;"><div style="display:table-cell;width:100%;height:100%;vertical-align:middle;text-align:center;line-height:1;padding:0 0 10px 0;box-sizing:border-box;">{{ place_text }}</div></div>
</div>

